function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof GECKO_INFO&&(e.innerHTML=GECKO_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderTaxonomy(){const e=document.getElementById("taxonomy-grid");e&&"undefined"!=typeof TAXONOMY_DATA&&(e.innerHTML=Object.entries(TAXONOMY_DATA).map(([e,n])=>`\n        <div class="tax-card">\n            <span class="tax-lbl">${e.toUpperCase()}:</span>\n            <span class="tax-val">${n}</span>\n        </div>\n    `).join(""))}function renderEcology(){if("undefined"==typeof ECOLOGY_BEHAVIOUR)return;const e=document.getElementById("eco-intro"),n=document.getElementById("eco-dist"),t=document.getElementById("eco-habitat"),o=document.getElementById("eco-morph"),r=document.getElementById("eco-behaviour"),i=document.getElementById("eco-diet"),d=document.getElementById("eco-repro"),s=document.getElementById("eco-conserve");e&&(e.innerHTML=`<strong>Introduction:</strong> ${ECOLOGY_BEHAVIOUR.introduction}`),n&&(n.innerHTML=`<strong>Geographic Distribution:</strong> ${ECOLOGY_BEHAVIOUR.distribution}`),t&&(t.innerHTML=`<strong>Habitat Preference:</strong> ${ECOLOGY_BEHAVIOUR.habitat}`),o&&(o.innerHTML=`<strong>Physical Characteristics & Morphology:</strong> ${ECOLOGY_BEHAVIOUR.morphology}`),r&&(r.innerHTML=`<strong>Nocturnal Behaviour & Activity:</strong> ${ECOLOGY_BEHAVIOUR.behaviour}`),i&&(i.innerHTML=`<strong>Diet & Feeding Habits:</strong> ${ECOLOGY_BEHAVIOUR.diet}`),d&&(d.innerHTML=`<strong>Reproduction & Nesting:</strong> ${ECOLOGY_BEHAVIOUR.reproduction}`),s&&(s.innerHTML=`<strong>Conservation Status & Threats:</strong> ${ECOLOGY_BEHAVIOUR.conservation}`)}function renderFacts(){const e=document.getElementById("facts-grid");e&&"undefined"!=typeof INTERESTING_FACTS&&(e.innerHTML=INTERESTING_FACTS.map(e=>`\n        <div class="fact-card">\n            <h3>✨ ${e.title}</h3>\n            <p>${e.description}</p>\n        </div>\n    `).join(""))}function renderGallery(){const e=document.getElementById("gallery-grid");e&&"undefined"!=typeof GALLERY_IMAGES&&(e.innerHTML=GALLERY_IMAGES.map(e=>`\n        <div class="gallery-card">\n            <img src="${e.url}" alt="${e.caption}" loading="lazy" />\n            <p>${e.caption}</p>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderTaxonomy(),renderEcology(),renderFacts(),renderGallery(),renderReferences(),initThemeToggle()});